import io, contextlib, traceback
from coding_impl import IMPL, DEBUG, PREDICT

def run_code_with_tests(code, tests):
    ns = {}
    exec(code, ns)
    tns = {}
    exec(tests, tns)
    tns["run_tests"](ns)

fails = []
for t in IMPL:
    try:
        run_code_with_tests(t["reference"], t["tests"])
    except Exception:
        fails.append((t["id"], "REFERENCE FAILED"))
        traceback.print_exc()

for t in DEBUG:
    try:
        run_code_with_tests(t["reference"], t["tests"])
    except Exception:
        fails.append((t["id"], "REFERENCE FAILED")); traceback.print_exc()
    try:
        run_code_with_tests(t["buggy"], t["tests"])
        fails.append((t["id"], "BUGGY VERSION PASSED (bad!)"))
    except Exception:
        pass  # expected

for t in PREDICT:
    buf = io.StringIO()
    try:
        with contextlib.redirect_stdout(buf):
            exec(t["code"], {})
        out = buf.getvalue().rstrip("\n")
        if out != t["answer"]:
            fails.append((t["id"], f"PREDICT MISMATCH:\nEXPECTED:\n{t['answer']}\nGOT:\n{out}"))
    except Exception:
        fails.append((t["id"], "PREDICT CODE CRASHED")); traceback.print_exc()

print(f"\n=== {len(IMPL)} impl, {len(DEBUG)} debug, {len(PREDICT)} predict ===")
if fails:
    print("FAILURES:")
    for f in fails: print(" -", f[0], f[1])
else:
    print("ALL TASKS VERIFIED OK")
"
}

